// Generated by OrchestKit Claude Plugin
// Created: 2026-03-11

/**
 * Unit tests for task-existence-gate hook
 * Tests advisory task-tracking nudges before agent spawns
 */

import { describe, test, expect, vi, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import type { HookInput } from '../../types.js';
import { mockCommonBasic } from '../fixtures/mock-common.js';

// =============================================================================
// Mocks — MUST be defined BEFORE imports
// =============================================================================

const mockGetTaskByAgent = vi.fn();

vi.mock('../../lib/task-integration.js', () => ({
  getTaskByAgent: (...args: unknown[]) => mockGetTaskByAgent(...args),
}));

vi.mock('../../lib/common.js', () => mockCommonBasic({
  getSessionId: vi.fn(() => 'test-session'),
}));

import { taskExistenceGate } from '../../pretool/task/task-existence-gate.js';
import { outputSilentSuccess, outputWithContext } from '../../lib/common.js';
import { claimTaskNudgeForInput } from '../../lib/task-nudge-gate.js';
import { createTestContext } from '../fixtures/test-context.js';

// =============================================================================
// Test Utilities
// =============================================================================

function createAgentInput(subagentType: string, overrides: Partial<HookInput> = {}): HookInput {
  return {
    tool_name: 'Agent',
    session_id: 'test-session',
    project_dir: '/test/project',
    tool_input: {
      subagent_type: subagentType,
      prompt: 'Do something',
    },
    ...overrides,
  };
}

// =============================================================================
// Tests
// =============================================================================

let testCtx: ReturnType<typeof createTestContext>;
let pluginData: string;
describe('task-existence-gate', () => {
  beforeEach(() => {
    // Isolate the once-per-session marker from the real session storage.
    pluginData = mkdtempSync(join(tmpdir(), 'task-gate-'));
    process.env.CLAUDE_PLUGIN_DATA = pluginData;
    testCtx = createTestContext({ sessionId: 'test-session' });
    vi.clearAllMocks();
    mockGetTaskByAgent.mockReturnValue(undefined);
  });

  afterEach(() => {
    vi.restoreAllMocks();
    rmSync(pluginData, { recursive: true, force: true });
    delete process.env.CLAUDE_PLUGIN_DATA;
  });

  // ---------------------------------------------------------------------------
  // Exempt agents — always pass silently
  // ---------------------------------------------------------------------------

  describe('exempt agents', () => {
    test.each([
      'Explore',
      'general-purpose',
      'Plan',
      'claude-code-guide',
      'statusline-setup',
    ])('exempt agent "%s" passes silently', (agentType) => {
      const input = createAgentInput(agentType);

      taskExistenceGate(input, testCtx);

      expect(outputSilentSuccess).toHaveBeenCalled();
      expect(outputWithContext).not.toHaveBeenCalled();
    });

    test('background agents are exempt', () => {
      const input: HookInput = {
        tool_name: 'Agent',
        session_id: 'test-session',
        project_dir: '/test/project',
        tool_input: {
          subagent_type: 'backend-system-architect',
          run_in_background: true,
        },
      };

      taskExistenceGate(input, testCtx);

      expect(outputSilentSuccess).toHaveBeenCalled();
    });
  });

  // ---------------------------------------------------------------------------
  // No task registered — advisory nudge (never blocks)
  // ---------------------------------------------------------------------------

  describe('no task registered', () => {
    test('returns advisory context when no task found', () => {
      mockGetTaskByAgent.mockReturnValue(undefined);
      const input = createAgentInput('backend-system-architect');

      const result = taskExistenceGate(input, testCtx);

      expect(outputWithContext).toHaveBeenCalledWith(
        expect.stringContaining('No task registered'),
        expect.anything(),
      );
      expect(result.continue).not.toBe(false);
    });

    test('advisory message includes agent name', () => {
      mockGetTaskByAgent.mockReturnValue(undefined);
      const input = createAgentInput('security-auditor');

      taskExistenceGate(input, testCtx);

      expect(outputWithContext).toHaveBeenCalledWith(
        expect.stringContaining('security-auditor'),
        expect.anything(),
      );
    });

    test('non-exempt ork agents still get the advisory nudge, never a block', () => {
      mockGetTaskByAgent.mockReturnValue(undefined);

      for (const agent of ['backend-system-architect', 'security-auditor', 'test-generator', 'code-quality-reviewer']) {
        vi.clearAllMocks();
        mockGetTaskByAgent.mockReturnValue(undefined);

        // one nudge per session, so each agent gets its own session here
        const input = createAgentInput(agent, { session_id: `session-${agent}` });
        const result = taskExistenceGate(input, testCtx);

        expect(outputWithContext).toHaveBeenCalled();
        expect(result.continue).not.toBe(false);
      }
    });
  });

  describe('once per session', () => {
    test('second spawn in the same session gets no nudge after the first was delivered', () => {
      mockGetTaskByAgent.mockReturnValue(undefined);
      const first = createAgentInput('security-auditor');
      taskExistenceGate(first, testCtx);
      expect(outputWithContext).toHaveBeenCalledTimes(1);
      expect(claimTaskNudgeForInput(first)).toBe(true); // what sync-task-dispatcher does

      vi.clearAllMocks();
      mockGetTaskByAgent.mockReturnValue(undefined);
      taskExistenceGate(createAgentInput('test-generator'), testCtx);
      expect(outputWithContext).not.toHaveBeenCalled();
      expect(outputSilentSuccess).toHaveBeenCalled();
    });

    test('missing session_id stays quiet', () => {
      mockGetTaskByAgent.mockReturnValue(undefined);
      taskExistenceGate(createAgentInput('security-auditor', { session_id: '' }), testCtx);
      expect(outputWithContext).not.toHaveBeenCalled();
    });
  });

  // ---------------------------------------------------------------------------
  // Task exists — silent pass
  // ---------------------------------------------------------------------------

  describe('task exists', () => {
    test('passes silently when task exists', () => {
      mockGetTaskByAgent.mockReturnValue({
        taskId: 'task-123',
        agent: 'backend-system-architect',
        status: 'pending',
      });
      const input = createAgentInput('backend-system-architect');

      taskExistenceGate(input, testCtx);

      expect(outputSilentSuccess).toHaveBeenCalled();
      expect(outputWithContext).not.toHaveBeenCalled();
    });
  });

  // ---------------------------------------------------------------------------
  // Edge cases
  // ---------------------------------------------------------------------------

  describe('edge cases', () => {
    test('handles missing subagent_type gracefully', () => {
      const input: HookInput = {
        tool_name: 'Agent',
        session_id: 'test-session',
        project_dir: '/test/project',
        tool_input: {},
      };

      const result = taskExistenceGate(input, testCtx);

      // Empty subagent_type defaults to 'unknown', not exempt
      expect(result.continue).toBeDefined();
    });

    test('handles non-string subagent_type', () => {
      const input: HookInput = {
        tool_name: 'Agent',
        session_id: 'test-session',
        project_dir: '/test/project',
        tool_input: { subagent_type: 42 },
      };

      const result = taskExistenceGate(input, testCtx);

      expect(result.continue).toBeDefined();
    });
  });
});
